/* Upload image */
add_action(
    'wp_ajax_upload_place_photo',
    'upload_place_photo'
);

function upload_place_photo()
{
    if (!is_user_logged_in()) {
        wp_send_json_error('Login required');
    }

    $place_id =
        sanitize_text_field(
            $_POST['place_id'] ?? ''
        );

    if (!$place_id) {
        wp_send_json_error('Place ID missing');
    }

    require_once ABSPATH .
        'wp-admin/includes/file.php';

    require_once ABSPATH .
        'wp-admin/includes/media.php';

    require_once ABSPATH .
        'wp-admin/includes/image.php';

    $attachment_id =
        media_handle_upload(
            'photo',
            0
        );

    if (is_wp_error($attachment_id)) {

        wp_send_json_error(
            $attachment_id->get_error_message()
        );

    }

    update_post_meta(
        $attachment_id,
        'place_id',
        $place_id
    );

    wp_send_json_success([
        'id' => $attachment_id,
        'url' => wp_get_attachment_url(
            $attachment_id
        )
    ]);
}
add_action(
    'wp_ajax_get_place_uploads',
    'get_place_uploads'
);
function get_place_uploads()
{
    $place_id =
        sanitize_text_field(
            $_GET['place_id'] ?? ''
        );

    $photos = get_posts([
        'post_type'      => 'attachment',
        'post_status'    => 'inherit',
        'posts_per_page' => -1,
        'meta_key'       => 'place_id',
        'meta_value'     => $place_id
    ]);

    $data = [];

    foreach ($photos as $photo) {

        $data[] = [
            'id'  => $photo->ID,
            'url' => wp_get_attachment_url(
                $photo->ID
            )
        ];
    }

    wp_send_json_success($data);
}
add_action('wp_ajax_pt_ai_search', 'pt_ai_search');
add_action('wp_ajax_nopriv_pt_ai_search', 'pt_ai_search');

function pt_ai_search()
{
    $question = sanitize_text_field(
        $_POST['question'] ?? ''
    );

    if (empty($question)) {
        wp_send_json_error([
            'message' => 'Question empty'
        ]);
    }

    $api_gemini_key = GEMINI_API_KEY;

    $response = wp_remote_post(
        'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' . $api_gemini_key,
        [
            'timeout' => 30,
            'headers' => [
                'Content-Type' => 'application/json'
            ],
            'body' => wp_json_encode([
                'contents' => [
                    [
                        'parts' => [
                            [
                                'text' => $question
                            ]
                        ]
                    ]
                ]
            ])
        ]
    );

    if (is_wp_error($response)) {
        wp_send_json_error([
            'message' => $response->get_error_message()
        ]);
    }

    $status = wp_remote_retrieve_response_code($response);

    $body = json_decode(
        wp_remote_retrieve_body($response),
        true
    );

    if ($status !== 200) {
        wp_send_json_error([
            'message' => 'Gemini API Error',
            'status'  => $status,
            'response' => $body
        ]);
    }

    $answer = '';

    if (!empty($body['candidates'][0]['content']['parts'])) {
        foreach (
            $body['candidates'][0]['content']['parts']
            as $part
        ) {
            $answer .= $part['text'] ?? '';
        }
    }

    wp_send_json_success([
        'answer' => nl2br($answer ?: 'Không tìm thấy kết quả')
    ]);
}
function pt_get_member_level_name( $user_id = 0 ) {

    global $wpdb;

    if ( ! $user_id ) {
        $user_id = get_current_user_id();
    }

    // Chưa đăng nhập
    if ( ! $user_id ) {
        return false;
    }

    $level_name = $wpdb->get_var(
        $wpdb->prepare(
            "SELECT l.name
             FROM {$wpdb->prefix}pmpro_memberships_users mu
             INNER JOIN {$wpdb->prefix}pmpro_membership_levels l
                ON mu.membership_id = l.id
             WHERE mu.user_id = %d
               AND mu.status = 'active'
             ORDER BY mu.id DESC
             LIMIT 1",
            $user_id
        )
    );

    return ! empty( $level_name ) ? $level_name : 'Free';
}

add_filter( 'gettext', 'pt_rename_buddymeet', 20, 3 );

function pt_rename_buddymeet( $translated, $text, $domain ) {

    if ( $translated === 'BuddyMeet' ) {
        return 'Meet';
    }

    if ( $text === 'BuddyMeet' ) {
        return 'Meet';
    }

    return $translated;
}

add_filter( 'gettext_with_context', 'pt_rename_buddymeet_context', 20, 4 );

function pt_rename_buddymeet_context( $translated, $text, $context, $domain ) {

    if ( $translated === 'BuddyMeet' || $text === 'BuddyMeet' ) {
        return 'Meet';
    }

    return $translated;
}

